export async function listCommercialDocuments(){const actor=await requirePermission("ACCOUNT_LEDGER_VIEW") as Actor;return db.commercialDocument.findMany({where:{companyId:actor.companyId,...scope(actor)},include:{lines:true},orderBy:{createdAt:"desc"}})}
export async function getCommercialDocument(id:string){const actor=await requirePermission("ACCOUNT_LEDGER_VIEW") as Actor,row=await db.commercialDocument.findFirst({where:{id,companyId:actor.companyId,...scope(actor)},include:{branch:true,lines:{orderBy:{position:"asc"}},reminders:{orderBy:{createdAt:"desc"}},adjustments:{where:{status:"POSTED"}},allocations:true,advanceApplications:true}});if(!row)throw new Error("NOT_FOUND");const financial=["SALES_INVOICE","PURCHASE_BILL"].includes(row.type)?await documentOutstanding(row.id):null;return{...row,financial}}
export async function commercialEditorOptions(){const actor=await requirePermission("ACCOUNT_LEDGER_VIEW") as Actor;const company=await db.company.findUniqueOrThrow({where:{id:actor.companyId},select:{productEdition:true}}),sourceRows=await db.commercialDocument.findMany({where:{companyId:actor.companyId,status:"POSTED",type:{in:["SALES_INVOICE","PURCHASE_BILL"]},...scope(actor)},select:{id:true,type:true,branchId:true,customerId:true,vendorId:true,documentNumber:true,grandTotal:true,adjustments:{where:{status:"POSTED"},select:{grandTotal:true}},allocations:{select:{amount:true}},advanceApplications:{select:{amount:true}},lines:{select:{id:true,lineType:true,itemName:true,productId:true,serviceId:true,workPackageId:true,quantity:true,rate:true,taxRate:true,lineTotal:true}}}}),sourceDocuments=sourceRows.map(x=>({...x,remainingAmount:x.advanceApplications.reduce((n,a)=>n.sub(a.amount),x.allocations.reduce((n,a)=>n.sub(a.amount),x.adjustments.reduce((n,a)=>n.sub(a.grandTotal),new D(x.grandTotal))))})).filter(x=>x.remainingAmount.gt(0));const enabledModules=await enabledModulesForCompany(actor.companyId),projects=await listOpenProjectOptionsForActor(actor,company.productEdition),purchaseOrders=await db.commercialDocument.findMany({where:{companyId:actor.companyId,type:"PURCHASE_ORDER",status:"POSTED",...scope(actor)},select:{id:true,documentNumber:true,branchId:true,vendorId:true,projectId:true,projectReference:true,grandTotal:true,taxableTotal:true,status:true}});const allowedDocumentTypes=availableCommercialDocumentTypes(enabledModules,permission=>canUsePermission(actor,company.productEdition,permission));return{sourceDocuments,purchaseOrders,enabledModules,allowedDocumentTypes,projects,branches:await db.branch.findMany({where:{companyId:actor.companyId,isActive:true,...(actor.branchAccessScope==="SELECTED_BRANCHES"?{id:{in:actor.branchIds??[]}}:{})},select:{id:true,name:true,code:true}}),customers:await db.customer.findMany({where:{companyId:actor.companyId,isActive:true,isAccountCustomer:true,...scope(actor)},select:{id:true,name:true}}),vendors:await db.vendor.findMany({where:{companyId:actor.companyId,isActive:true},select:{id:true,name:true}}),products:await db.accountProduct.findMany({where:{companyId:actor.companyId,isActive:true},select:{id:true,name:true,code:true,salePrice:true,costPrice:true,taxRate:true,trackInventory:true,trackingMode:true}}),warehouses:await db.warehouse.findMany({where:{companyId:actor.companyId,isActive:true,...scope(actor)},select:{id:true,name:true,branchId:true}}),batches:await db.inventoryBatch.findMany({where:{companyId:actor.companyId},select:{id:true,productId:true,batchNumber:true,expiryDate:true}}),serials:await db.inventorySerialNumber.findMany({where:{companyId:actor.companyId},select:{id:true,productId:true,serialNumber:true,expiryDate:true}}),accountSettings:await db.accountSettings.findUnique({where:{companyId:actor.companyId!}}),services:await db.accountService.findMany({where:{companyId:actor.companyId,isActive:true},select:{id:true,name:true,code:true,sellingRate:true,taxRate:true}}),workPackages:await db.workPackage.findMany({where:{companyId:actor.companyId,isActive:true},select:{id:true,name:true,code:true,sellingRate:true}})}}
export async function commercialDocumentControls(documentId:string){const actor=await requirePermission("ACCOUNT_LEDGER_VIEW") as Actor,document=await db.commercialDocument.findFirst({where:{id:documentId,companyId:actor.companyId,status:"POSTED",...scope(actor)},select:{id:true,type:true,branchId:true,customerId:true,vendorId:true,balanceDue:true}});if(!document)return{canManage:false,canRemind:false,advances:[],enabledModules:[] as ModuleKey[]};const enabledModules=await enabledModulesForCompany(actor.companyId),canManage=actor.accountRole==="ACCOUNT_ADMIN"||actor.accountRole==="ACCOUNTANT",customer=document.type==="SALES_INVOICE",advanceType=customer?"CUSTOMER_ADVANCE":"VENDOR_ADVANCE",advanceModule=customer?"CUSTOMER_ADVANCES":"VENDOR_ADVANCES",advances=canManage&&enabledModules.includes(advanceModule)?await db.accountSettlement.findMany({where:{companyId:actor.companyId,branchId:document.branchId,type:advanceType,remainingAmount:{gt:0},...(customer?{customerId:document.customerId}:{vendorId:document.vendorId})},select:{id:true,settlementNumber:true,remainingAmount:true}}):[];return{canManage,canRemind:canManage&&customer&&enabledModules.includes("SALES")&&enabledModules.includes("PAYMENT_REMINDERS"),advances,enabledModules}}

export async function documentOutstandingsBatch(companyId:string,documents:Array<{id:string;grandTotal:Prisma.Decimal;payableAmount:Prisma.Decimal|null}>){if(!documents.length)return new Map<string,Prisma.Decimal>();const ids=documents.map(x=>x.id),[adjustments,allocations,applications]=await Promise.all([db.commercialDocument.findMany({where:{companyId,status:"POSTED",sourceDocumentId:{in:ids}},select:{sourceDocumentId:true,grandTotal:true,payableAmount:true}}),db.settlementAllocation.groupBy({by:["documentId"],where:{companyId,documentId:{in:ids}},_sum:{amount:true}}),db.advanceApplication.groupBy({by:["documentId"],where:{companyId,documentId:{in:ids}},_sum:{amount:true}})]),adjustmentMap=adjustments.reduce((map,x)=>map.set(x.sourceDocumentId!,(map.get(x.sourceDocumentId!)??new D(0)).add(x.payableAmount??x.grandTotal)),new Map<string,Prisma.Decimal>()),allocationMap=new Map(allocations.map(x=>[x.documentId,new D(x._sum.amount??0)])),applicationMap=new Map(applications.map(x=>[x.documentId,new D(x._sum.amount??0)]));return new Map(documents.map(doc=>{const outstanding=new D(doc.payableAmount??doc.grandTotal).sub(adjustmentMap.get(doc.id)??0).sub(allocationMap.get(doc.id)??0).sub(applicationMap.get(doc.id)??0);if(outstanding.lt(0))throw new Error("NEGATIVE_OUTSTANDING");return[doc.id,outstanding]}));}

export function purchasePostingAllocation(input:{taxable:Prisma.Decimal;tax:Prisma.Decimal;trackedTaxable:Prisma.Decimal;trackedTax:Prisma.Decimal;eligible:boolean;reverseCharge:boolean;tds?:Prisma.Decimal}){const inventory=input.trackedTaxable.add(input.eligible?0:input.trackedTax),nonInventory=input.taxable.sub(input.trackedTaxable).add(input.eligible?0:input.tax.sub(input.trackedTax)),itc=input.eligible?input.tax:new D(0),rcmLiability=input.reverseCharge?input.tax:new D(0),vendorPayable=input.taxable.add(input.reverseCharge?0:input.tax).sub(input.tds??0);return{inventory,nonInventory,itc,rcmLiability,vendorPayable,totalDebit:inventory.add(nonInventory).add(itc),totalCredit:vendorPayable.add(rcmLiability).add(input.tds??0)}}
export function proportionalTaxReversal(sourceTax:Prisma.Decimal,sourceTaxable:Prisma.Decimal,adjustmentTaxable:Prisma.Decimal){if(sourceTaxable.lte(0)||adjustmentTaxable.lt(0)||adjustmentTaxable.gt(sourceTaxable))throw new Error("INVALID_ADJUSTMENT_BASIS");return sourceTax.mul(adjustmentTaxable).div(sourceTaxable).toDecimalPlaces(2)}

export function adjustmentTaxableBasis(sourceTaxable:Prisma.Decimal,sourceTotal:Prisma.Decimal,enteredAmount:Prisma.Decimal,taxMode:"EXCLUSIVE"|"INCLUSIVE"){if(enteredAmount.lt(0)||sourceTaxable.lt(0)||sourceTotal.lte(0)||enteredAmount.gt(sourceTotal))throw new Error("INVALID_ADJUSTMENT_BASIS");return taxMode==="INCLUSIVE"?sourceTaxable.mul(enteredAmount).div(sourceTotal).toDecimalPlaces(2):enteredAmount.toDecimalPlaces(2)}
